window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-28c034dd889c7ed1"]={"versions": [{"id": "FIG-28c034dd889c7ed1", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Transformations- und Abbildungsdiagramm im Kontext von AUTOSAR Classic (TR Interaction With Behavioral Models). Das Diagramm illustriert das architektonische Transformationsprinzip, bei dem eine vorbestehende, hierarchisch gegliederte Verhaltensmodellstruktur (z. B. aus einem Behavioral Modeling Tool wie Simulink/Stateflow oder Ascet) vollständig in eine gekapselte atomare Software-Komponente (<code>AtomicSoftwareComponentType</code>) überführt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Hierarchical Behavioral Model Structure</strong>: Hierarchie aus Verhaltensmodellen mit einem Top-Level-Knoten <code>Behav. Model i</code> und untergeordneten Kindknoten <code>Behav. Model j</code> sowie <code>Behav. Model k</code>, verbunden über Verzweigungslinien.</li>\n<li><strong>Atomic Software Component (<code>SW-C l</code>)</strong>: Zielentität der AUTOSAR-Modellierung, die das gesamte Verhaltensmodell nach außen kapselt.</li>\n<li><strong>Transformationspfeil</strong>: Ein breiter, nach links gerichteter Blockpfeil mit der annotierten Transformationssemantik „SW-C is encapsulation of the full behavioral model“. Schnittstellen der obersten Hierarchieebene (<code>Behav. Model i</code>) definieren die Ports/Interfaces der gekapselten Software-Komponente.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Abbildungs- bzw. Transformationsschema: Der Prozess überführt eine hierarchische Verhaltensmodellstruktur (Rechts) gerichtet in eine AUTOSAR-SW-C-Beschreibung (Links). Die interne Hierarchie und Interaktionsstruktur zwischen den Sub-Modellen <code>j</code> und <code>k</code> unter <code>i</code> wird innerhalb der Komponente <code>SW-C l</code> verborgen; nach außen hin exponiert die Komponente ausschließlich die Schnittstellen der Top-Level-Ebene <code>i</code>. Es handelt sich um eine strukturelle Kapselung ohne Darstellung zeitlicher Laufzeitsequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung visualisiert die Anforderung an Modell-Konverter, legacy Verhaltensmodelle nicht zwingend in eine AUTOSAR-Kompositionsstruktur zu zerlegen, sondern als eine einzelne gekapselte atomare Software-Komponente zu importieren. Für Tool-Entwickler und Systemarchitekten bedeutet dies, dass interne Subsystem-Schnittstellen nicht auf VFB- oder RTE-Ebene modelliert werden müssen, sondern als interne Implementierungsdetails der Komponente verbleiben, während lediglich Top-Level-Ports in die SW-C-Description übernommen werden.</p>"}, {"id": "FIG-ae1d48a83eb6b352", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Transformations- und Abbildungsdiagramm im Kontext von AUTOSAR Classic (TR Interaction With Behavioral Models). Das Diagramm illustriert das architektonische Transformationsprinzip, bei dem eine vorbestehende, hierarchisch gegliederte Verhaltensmodellstruktur (z. B. aus einem Behavioral Modeling Tool wie Simulink/Stateflow oder Ascet) vollständig in eine gekapselte atomare Software-Komponente (<code>AtomicSoftwareComponentType</code>) überführt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Hierarchical Behavioral Model Structure</strong>: Hierarchie aus Verhaltensmodellen mit einem Top-Level-Knoten <code>Behav. Model i</code> und untergeordneten Kindknoten <code>Behav. Model j</code> sowie <code>Behav. Model k</code>, verbunden über Verzweigungslinien.</li>\n<li><strong>Atomic Software Component (<code>SW-C l</code>)</strong>: Zielentität der AUTOSAR-Modellierung, die das gesamte Verhaltensmodell nach außen kapselt.</li>\n<li><strong>Transformationspfeil</strong>: Ein breiter, nach links gerichteter Blockpfeil mit der annotierten Transformationssemantik „SW-C is encapsulation of the full behavioral model“. Schnittstellen der obersten Hierarchieebene (<code>Behav. Model i</code>) definieren die Ports/Interfaces der gekapselten Software-Komponente.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Abbildungs- bzw. Transformationsschema: Der Prozess überführt eine hierarchische Verhaltensmodellstruktur (Rechts) gerichtet in eine AUTOSAR-SW-C-Beschreibung (Links). Die interne Hierarchie und Interaktionsstruktur zwischen den Sub-Modellen <code>j</code> und <code>k</code> unter <code>i</code> wird innerhalb der Komponente <code>SW-C l</code> verborgen; nach außen hin exponiert die Komponente ausschließlich die Schnittstellen der Top-Level-Ebene <code>i</code>. Es handelt sich um eine strukturelle Kapselung ohne Darstellung zeitlicher Laufzeitsequenzen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung visualisiert die Anforderung an Modell-Konverter, legacy Verhaltensmodelle nicht zwingend in eine AUTOSAR-Kompositionsstruktur zu zerlegen, sondern als eine einzelne gekapselte atomare Software-Komponente zu importieren. Für Tool-Entwickler und Systemarchitekten bedeutet dies, dass interne Subsystem-Schnittstellen nicht auf VFB- oder RTE-Ebene modelliert werden müssen, sondern als interne Implementierungsdetails der Komponente verbleiben, während lediglich Top-Level-Ports in die SW-C-Description übernommen werden.</p>"}], "trans": [{"from": "FIG-28c034dd889c7ed1", "to": "FIG-ae1d48a83eb6b352", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
